  1	/**
  2	 * Interval-based scheduler started from `src/instrumentation.ts`; decides which job kind is due.
  3	 */
  4	import { createLogger } from "@/lib/logger";
  5	import { drain, enqueue, pendingCount } from "./queue";
  6	import { toIsoTimestamp } from "@/types/common";
  7	import type { JobKind } from "./queue";
  8	
  9	/** How often `tick()` runs once the scheduler is started. */
 10	const TICK_INTERVAL_MS = 60_000;
 11	
 12	/** Minimum gap between two runs of the same job kind, in minutes. */
 13	const CADENCE_MINUTES: Readonly<Record<JobKind, number>> = {
 14	  "digest-email": 60,
 15	  "overdue-issues": 60,
 16	  "webhook-delivery": 1,
 17	  "usage-rollup": 15,
 18	  "search-reindex": 1_440,
 19	  "cleanup-archived": 1_440,
 20	  "trial-expiry": 360,
 21	};
 22	
 23	const logger = createLogger("job-scheduler");
 24	
 25	let timer: ReturnType<typeof setInterval> | null = null;
 26	const lastRunAt = new Map<JobKind, number>();
 27	
 28	/**
 29	 * Starts the interval. Idempotent, and `unref()`ed so a pending tick never
 30	 * keeps a process alive — a scheduler that blocks shutdown is worse than one
 31	 * that misses the last tick.
 32	 */
 33	export function startScheduler(): void {
 34	  if (timer !== null) return;
 35	
 36	  timer = setInterval(() => {
 37	    void tick(new Date()).catch((error: unknown) => {
 38	      logger.error("scheduler tick failed", {
 39	        reason: error instanceof Error ? error.message : String(error),
 40	      });
 41	    });
 42	  }, TICK_INTERVAL_MS);
 43	
 44	  timer.unref?.();
 45	  logger.info("scheduler started", { intervalMs: TICK_INTERVAL_MS });
 46	}
 47	
 48	export function stopScheduler(): void {
 49	  if (timer === null) return;
 50	  clearInterval(timer);
 51	  timer = null;
 52	  lastRunAt.clear();
 53	}
 54	
 55	export function isSchedulerRunning(): boolean {
 56	  return timer !== null;
 57	}
 58	
 59	/**
 60	 * One pass: enqueue whatever cadence says is due, then drain the queue. Split
 61	 * out from the interval so tests can drive it with an explicit clock instead
 62	 * of waiting a minute.
 63	 */
 64	export async function tick(now: Date): Promise<void> {
 65	  for (const kind of Object.keys(CADENCE_MINUTES) as JobKind[]) {
 66	    if (!isDue(kind, now)) continue;
 67	
 68	    lastRunAt.set(kind, now.getTime());
 69	    enqueue({
 70	      id: `${kind}:${Math.floor(now.getTime() / 60_000)}`,
 71	      kind,
 72	      runAt: toIsoTimestamp(now),
 73	      attempts: 0,
 74	      payload: {},
 75	    });
 76	  }
 77	
 78	  const completed = await drain();
 79	  if (completed > 0 || pendingCount() > 0) {
 80	    logger.debug("tick complete", { completed, pending: pendingCount() });
 81	  }
 82	}
 83	
 84	function isDue(kind: JobKind, now: Date): boolean {
 85	  const previous = lastRunAt.get(kind);
 86	  if (previous === undefined) return true;
 87	  return now.getTime() - previous >= CADENCE_MINUTES[kind] * 60_000;
 88	}
  1	/**
  2	 * Barrel for the job layer.
  3	 *
  4	 * `instrumentation.ts` imports `startScheduler` from here; everything else in
  5	 * the app talks to jobs by emitting an event, never by calling a runner
  6	 * directly. The individual `run*Job` functions are exported for the admin
  7	 * "run now" action and for the test suite.
  8	 */
  9	export {
 10	  drain,
 11	  enqueue,
 12	  pendingCount,
 13	  resetQueue,
 14	} from "./queue";
 15	export type { JobKind, QueuedJob } from "./queue";
 16	
 17	export {
 18	  isSchedulerRunning,
 19	  startScheduler,
 20	  stopScheduler,
 21	  tick,
 22	} from "./scheduler";
 23	
 24	export { emptyJobResult } from "./types";
 25	export type { JobResult } from "./types";
 26	
 27	export { runCleanupArchivedJob } from "./cleanup-archived-job";
 28	export { runDigestEmailJob, shouldRunForOrg } from "./digest-email-job";
 29	export { runOverdueIssueJob } from "./overdue-issue-job";
 30	export { runSearchReindexJob } from "./search-reindex-job";
 31	export { runTrialExpiryJob } from "./trial-expiry-job";
 32	export { runUsageRollupJob } from "./usage-rollup-job";
 33	export { backoffMs, runWebhookDeliveryJob } from "./webhook-delivery-job";
  1	/**
  2	 * Minimal in-process job queue: enqueue, drain, retry with backoff. Jobs never run inside a request.
  3	 */
  4	import { createLogger } from "@/lib/logger";
  5	import { toIsoTimestamp } from "@/types/common";
  6	import type { IsoTimestamp } from "@/types/common";
  7	
  8	export type QueuedJob = {
  9	  id: string;
 10	  kind: JobKind;
 11	  runAt: IsoTimestamp;
 12	  attempts: number;
 13	  payload: Readonly<Record<string, unknown>>;
 14	};
 15	
 16	export type JobKind =
 17	  | "digest-email"
 18	  | "overdue-issues"
 19	  | "webhook-delivery"
 20	  | "usage-rollup"
 21	  | "search-reindex"
 22	  | "cleanup-archived"
 23	  | "trial-expiry";
 24	
 25	/** Attempts after which a job is dropped rather than retried again. */
 26	const MAX_ATTEMPTS = 5;
 27	
 28	/** How many jobs `drain()` takes in one pass when no limit is given. */
 29	const DEFAULT_DRAIN = 25;
 30	
 31	const logger = createLogger("job-queue");
 32	
 33	/**
 34	 * The queue lives in module scope: Taskflow runs one server process and the
 35	 * scheduler is started from `instrumentation.ts`, so there is no second
 36	 * consumer to coordinate with. Swapping this for a real broker means
 37	 * reimplementing these four functions and nothing else.
 38	 */
 39	const pending: QueuedJob[] = [];
 40	
 41	/** Idempotent on `id`: re-enqueuing a job keeps the earlier `runAt`. */
 42	export function enqueue(job: QueuedJob): void {
 43	  if (pending.some((queued) => queued.id === job.id)) return;
 44	  pending.push(job);
 45	}
 46	
 47	/**
 48	 * Runs everything that is due, oldest first. A handler that throws is put back
 49	 * with an exponential delay until `MAX_ATTEMPTS`, then dropped with a log line
 50	 * — an infinitely retrying job is worse than a lost one.
 51	 */
 52	export async function drain(limit: number = DEFAULT_DRAIN): Promise<number> {
 53	  const now = new Date().toISOString();
 54	  const due = pending
 55	    .filter((job) => job.runAt <= now)
 56	    .sort((a, b) => (a.runAt < b.runAt ? -1 : 1))
 57	    .slice(0, Math.max(0, limit));
 58	
 59	  let completed = 0;
 60	
 61	  for (const job of due) {
 62	    remove(job.id);
 63	
 64	    try {
 65	      await runHandler(job);
 66	      completed += 1;
 67	    } catch (error) {
 68	      const attempts = job.attempts + 1;
 69	
 70	      if (attempts >= MAX_ATTEMPTS) {
 71	        logger.error("job dropped after max attempts", {
 72	          id: job.id,
 73	          kind: job.kind,
 74	          attempts,
 75	        });
 76	        continue;
 77	      }
 78	
 79	      pending.push({
 80	        ...job,
 81	        attempts,
 82	        runAt: toIsoTimestamp(new Date(Date.now() + backoffMs(attempts))),
 83	      });
 84	
 85	      logger.warn("job retry scheduled", {
 86	        id: job.id,
 87	        kind: job.kind,
 88	        attempts,
 89	        reason: error instanceof Error ? error.message : String(error),
 90	      });
 91	    }
 92	  }
 93	
 94	  return completed;
 95	}
 96	
 97	export function pendingCount(): number {
 98	  return pending.length;
 99	}
100	
101	/** Test hook: empties the queue. Never call this from application code. */
102	export function resetQueue(): void {
103	  pending.length = 0;
104	}
105	
106	/** 1s, 2s, 4s, 8s … capped at one minute. */
107	function backoffMs(attempts: number): number {
108	  return Math.min(60_000, 2 ** (attempts - 1) * 1_000);
109	}
110	
111	function remove(id: string): void {
112	  const at = pending.findIndex((job) => job.id === id);
113	  if (at >= 0) pending.splice(at, 1);
114	}
115	
116	/**
117	 * Dispatches one queued job to its runner. The imports are dynamic so the
118	 * queue module stays free of a cycle: every job module imports this one to
119	 * enqueue follow-up work.
120	 */
121	async function runHandler(job: QueuedJob): Promise<void> {
122	  const now = new Date();
123	
124	  switch (job.kind) {
125	    case "digest-email": {
126	      const { runDigestEmailJob } = await import("./digest-email-job");
127	      await runDigestEmailJob(now);
128	      return;
129	    }
130	    case "overdue-issues": {
