     1	import {
     2	  FEATURE_FLAG_DEFINITIONS,
     3	  FEATURE_FLAG_KEYS,
     4	} from "@/config/feature-flags";
     5	import { planAtLeast } from "@/config/plan-limits";
     6	import { ROLE_RANK } from "@/types/member";
     7	import type {
     8	  FeatureFlagKey,
     9	  FeatureFlagSnapshot,
    10	  FlagContext,
    11	} from "@/types/feature-flag";
    12	
    13	/**
    14	 * Feature-flag evaluation, shared verbatim by server and client.
    15	 *
    16	 * Server code builds a `FlagContext` from the session and calls `isEnabled()`
    17	 * directly; the dashboard layout serialises `snapshotFlags()` into the client
    18	 * provider so `useFeatureFlag()` answers the same way without a round trip.
    19	 * Both sides must agree — never re-implement a strategy at a call site.
    20	 */
    21	export function isEnabled(flag: FeatureFlagKey, ctx: FlagContext): boolean {
    22	  const definition = FEATURE_FLAG_DEFINITIONS[flag];
    23	  if (!definition) return false;
    24	
    25	  if (definition.overridable && ctx.overrides?.includes(flag)) {
    26	    return true;
    27	  }
    28	
    29	  const strategy = definition.strategy;
    30	  switch (strategy.kind) {
    31	    case "off":
    32	      return false;
    33	    case "on":
    34	      return true;
    35	    case "plan":
    36	      return planAtLeast(ctx.plan, strategy.minPlan);
    37	    case "role":
    38	      return ctx.role !== null && ROLE_RANK[ctx.role] >= ROLE_RANK[strategy.minRole];
    39	    case "percentage":
    40	      return bucketOf(flag, ctx) < strategy.percent;
    41	    default:
    42	      return false;
    43	  }
    44	}
    45	
    46	/** Evaluates every flag at once, for handoff to the client provider. */
    47	export function snapshotFlags(ctx: FlagContext): FeatureFlagSnapshot {
    48	  const snapshot = {} as Record<FeatureFlagKey, boolean>;
    49	  for (const key of FEATURE_FLAG_KEYS) {
    50	    snapshot[key] = isEnabled(key, ctx);
    51	  }
    52	  return snapshot;
    53	}
    54	
    55	/** Throwing guard for server actions gated behind a flag. */
    56	export class FeatureDisabledError extends Error {
    57	  readonly code = "forbidden" as const;
    58	
    59	  constructor(readonly flag: FeatureFlagKey) {
    60	    super(`Feature "${flag}" is not enabled for this organization.`);
    61	    this.name = "FeatureDisabledError";
    62	  }
    63	}
    64	
    65	export function assertEnabled(flag: FeatureFlagKey, ctx: FlagContext): void {
    66	  if (!isEnabled(flag, ctx)) {
    67	    throw new FeatureDisabledError(flag);
    68	  }
    69	}
    70	
    71	/**
    72	 * Deterministic 0–99 bucket for percentage rollouts. Stable per
    73	 * (flag, org, user) so a viewer never sees the feature flicker.
    74	 */
    75	function bucketOf(flag: FeatureFlagKey, ctx: FlagContext): number {
    76	  const seed = `${flag}:${ctx.orgId ?? "-"}:${ctx.userId ?? "-"}`;
    77	  let hash = 2_166_136_261;
    78	  for (let i = 0; i < seed.length; i += 1) {
    79	    hash ^= seed.charCodeAt(i);
    80	    hash = Math.imul(hash, 16_777_619);
    81	  }
    82	  return Math.abs(hash) % 100;
    83	}
